from pathlib import Path
import json,subprocess,hashlib,datetime,shutil
r=Path('C:/.projects/venus');out=r/'.artifacts/p05-a15-owned-cpu-profile01';assert not out.exists();out.mkdir();project='venus-pilot470-04ed27eff134';expected='sha256:d1eff08f9a3201c087356bef173ab5b5df7ea202125d6e30aceaec090cbe893c'
def run(args,**kw):
 p=subprocess.run(['docker']+args,capture_output=True,text=True,encoding='utf-8',timeout=45,**kw);assert p.returncode==0,(args[0],p.returncode,p.stderr[:500]);return p
ids=run(['ps','-q','--filter','label=com.docker.compose.project='+project,'--filter','label=com.docker.compose.service=app']).stdout.split();assert len(ids)==1
cid=ids[0]
def owned():
 x=json.loads(run(['inspect',cid]).stdout)[0];assert x['Config']['Labels']['com.docker.compose.project']==project and x['Config']['Labels']['com.docker.compose.service']=='app';assert x['Image']==expected and x['Config']['Cmd']==['node','apps/api/dist/server.js'];assert x['State']['Running'];assert '9229/tcp'not in(x['NetworkSettings']['Ports']or{});return {'id':x['Id'],'image':x['Image'],'project':project,'service':'app','command':x['Config']['Cmd'],'ports':x['NetworkSettings']['Ports']}
(out/'inspect-before.json').write_text(json.dumps(owned(),indent=2)+'\n',encoding='utf-8');
progress_js="import fs from'node:fs';const d=JSON.parse(fs.readFileSync('/tmp/pilot470-report.json'));console.log(JSON.stringify({status:d.status,completed_rounds:d.completed_rounds,profiles:d.profiles.map(x=>({N:x.N,status:x.status,rounds:x.rounds.length})),last_request:d.last_request?{operation:d.last_request.operation,status:d.last_request.status,duration_ms:d.last_request.duration_ms,round_index:d.last_request.round_index}:null}));"
progress=run(['exec',cid,'node','--input-type=module','-e',progress_js]);(out/'public-progress-before.json').write_text(progress.stdout,encoding='utf-8')
source=r/'.artifacts/p05-a11-owned-cpu-profile01/capture.mjs';shutil.copyfile(source,out/'capture.mjs');assert (out/'capture.mjs').read_bytes()==source.read_bytes()
p=run(['exec','-i',cid,'node','--input-type=module'],input=source.read_text());assert len(p.stdout.encode())<=8*1024**2;(out/'cpu-profile.json').write_text(p.stdout,encoding='utf-8',newline='\n');(out/'capture-stderr.txt').write_text(p.stderr,encoding='utf-8',newline='\n');d=json.loads(p.stdout);assert d['requested_profile_ms']==7000
(out/'inspect-after.json').write_text(json.dumps(owned(),indent=2)+'\n',encoding='utf-8');listener_js=r"import fs from'node:fs';const listeners=p=>fs.readFileSync(p,'utf8').split('\n').map(x=>x.trim().split(/\s+/)).filter(x=>x[3]==='0A'&&x[1]?.endsWith(':240D')).map(x=>x[1]);console.log(JSON.stringify({tcp:listeners('/proc/net/tcp'),tcp6:listeners('/proc/net/tcp6')}));"
listener=run(['exec',cid,'node','--input-type=module','-e',listener_js]);(out/'listener-after.json').write_text(listener.stdout,encoding='utf-8');assert json.loads(listener.stdout)=={'tcp':['0100007F:240D'],'tcp6':[]}

shutil.copyfile(r/'.artifacts/p05-a11-owned-cpu-profile01/aggregate.py',out/'aggregate.py');q=subprocess.run([str(r/'.venv/Scripts/python.exe'),'-X','utf8','-B',str(out/'aggregate.py')],cwd=r,capture_output=True,text=True);assert q.returncode==0,q.stderr
(out/'receipt.json').write_text(json.dumps({'created_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'status':'ONE_OWNED_7S_CPU_PROFILE_CAPTURED_NOT_FUNCTIONAL_OR_LATENCY_PASS','capture_exit':p.returncode,'aggregate_exit':q.returncode,'project':project,'image':expected,'source_identity':'658b710bdca35b678421a51c1c276028305f28362901b2c065a3867aa754f4de','unchanged_prior_capture_sha256':hashlib.sha256(source.read_bytes()).hexdigest(),'instrumented_cohort':'in_person/questions','normal_uninstrumented_cohort_acceptance':False,'private_payload_or_heap':False,'listener_cleanup':'EXISTING_PARENT_COHORT_COMPOSE_TEARDOWN'},indent=2)+'\n',encoding='utf-8');a=json.loads((out/'AGGREGATES.json').read_text());print(json.dumps({'capture_exit':0,'profile_ms':a['profile_elapsed_ms'],'top_self':a['top_self'][:5],'top_inclusive':a['top_inclusive'][:5]}))
